const data = $input.first().json.body.data;
const requestedOutputs = data.requested_outputs || {};

let items = [];

for (const [outputType, count] of Object.entries(requestedOutputs)) {
  if (Number(count) > 0) {
    items.push({
      json: {
        project_id: data.project_id,
        generation_job_id: data.generation_job_id,
        transcript_id: data.transcript_id,
        output_type: outputType // نام مستقیم پلتفرم برای بررسی در سوئیچ
      }
    });
  }
}

return items;

