const generationJobId = $('Webhook').first().json.body.data.generation_job_id;

// ۲. دریافت محتوای استخراج شده از ورودی همین نود (خروجی هوش مصنوعی)
const aiContent = $input.first().json.output.content;

// ۳. ساخت ساختار استاندارد خروجی در n8n
return [{
  json: {
    generation_job_id: generationJobId,
    content: aiContent,
    metadata: {
      llm_used: "deepseek-v4-flash, gpt-4o"
    }
  }
}];

// ۱. دریافت داده‌های پایه از وب‌هوک
const webhookData = $('Webhook').first().json.body.data;
const projectId = webhookData.project_id;
const generationJobId = webhookData.generation_job_id;
const transcriptId = webhookData.transcript_id;

// ۲. دریافت آبجکت حاوی پرامپت‌ها از گره Code in JavaScript1
// (جایی که canonical_representation ساخته شده است)
const canonicalData = $('Code in JavaScript1').first().json.content.canonical_representation;

let imageItems = [];
let counter = 1;

// ۳. جستجوی داینامیک برای هر کلیدی که شامل "image_prompt" باشد
for (const key in canonicalData) {
  if (key.includes('image_prompt')) {
    const promptText = canonicalData[key];

    // اطمینان از اینکه پرامپت خالی نیست
    if (promptText && promptText.trim() !== "") {
      imageItems.push({
        json: {
          task_type: "image_generation",
          image_index: counter,         // شماره عکس (۱، ۲، ۳ و...)
          image_prompt: promptText,     // متن سوپرپرامپت استخراج شده
          prompt_key: key,              // نام کلید (مثلا image_prompt1)
          project_id: projectId,
          generation_job_id: generationJobId,
          transcript_id: transcriptId
        }
      });
      counter++;
    }
  }
}

// ۴. بازگرداندن آرایه آیتم‌ها برای ورود به نود Loop
return imageItems;

