const items = $input.all();
let result = [];

for (let i = 0; i < items.length; i++) {
  const json = items[i].json;

  // ۱. پیدا کردن رشته متنی تصویر از خروجی گره قبل
  const dataUri = json.body?.choices?.[0]?.message?.images?.[0]?.image_url?.url;

  if (!dataUri) {
    throw new Error('تصویری در خروجی API یافت نشد.');
  }

  // ۲. جداسازی پیشوند (data:image/png;base64) از دیتای اصلی بیس ۶۴
  const parts = dataUri.split(',');
  const mimeMatch = parts[0].match(/:(.*?);/);
  const mimeType = mimeMatch ? mimeMatch[1] : 'image/png';
  const base64Data = parts[1] || parts[0]; 

  // ۳. تعیین پسوند فایل بر اساس نوع Mime
  let extension = 'png';
  if (mimeType.includes('jpeg') || mimeType.includes('jpg')) extension = 'jpg';
  else if (mimeType.includes('webp')) extension = 'webp';

  // ۴. تبدیل بیس ۶۴ به بافر (Buffer)
  const buffer = Buffer.from(base64Data, 'base64');

  // ۵. ایجاد فرمت باینری استاندارد برای n8n و حفظ دیتای json قبلی
  result.push({
    json: json,
    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        `generated-image-${json.image_index || i}.${extension}`,
        mimeType
      )
    }
  });
}

return result;

// ۱. دریافت تمام آیتم‌های ورودی
let items = $input.all().map(item => item.json);

// ۲. مرتب‌سازی آیتم‌ها بر اساس زمان (createdAt) از قدیمی‌ترین به جدیدترین
items.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

// ۳. استخراج لینک‌ها و حذف موارد تکراری (برای رفع مشکل تکرار ۳ باره دیتا در حلقه)
const uniqueLinks = [...new Set(items.map(item => item.link))];

// ۴. تبدیل لینک‌های خام به آبجکت استاندارد مورد نیاز بک‌اند
const mediaLinks = uniqueLinks.map(link => {
  return { storage_path: link };
});

// ۵. برگرداندن خروجی نهایی به صورت یکپارچه
return [{
  json: {
    links: mediaLinks
  }
}];

