// ۱. استخراج آرایه اسلایدها از خروجی نود هوش مصنوعی
const slides = $input.first().json.output.slides || [];

// ۲. تبدیل هر اسلاید به یک آیتم مستقل برای ورود به حلقه (Loop)
const items = slides.map(slide => {
  return {
    json: {
      slide_index: slide.index,
      title: slide.title,
      text: slide.text,
      description: slide.description,
      image_prompt: slide.image_prompt
    }
  };
});

// ۳. بازگرداندن آیتم‌های تفکیک‌شده
return items;

